-- Wordle games table
CREATE TABLE IF NOT EXISTS wordle_games (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  team_member_id TEXT REFERENCES team(id) NOT NULL,
  word TEXT NOT NULL,
  guesses TEXT[] DEFAULT '{}',
  solved BOOLEAN DEFAULT false,
  played_date DATE NOT NULL,
  created_at TIMESTAMPTZ DEFAULT now(),
  UNIQUE(team_member_id, played_date)
);

ALTER TABLE wordle_games ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Users can read own wordle games"
  ON wordle_games FOR SELECT TO authenticated USING (true);
CREATE POLICY "Users can insert wordle games"
  ON wordle_games FOR INSERT TO authenticated WITH CHECK (true);
CREATE POLICY "Users can update own wordle games"
  ON wordle_games FOR UPDATE TO authenticated USING (true);

-- Add difficulty column to trivia
ALTER TABLE trivia_questions ADD COLUMN IF NOT EXISTS difficulty TEXT DEFAULT 'Easy';

-- Set existing questions to Medium
UPDATE trivia_questions SET difficulty = 'Medium' WHERE difficulty IS NULL OR difficulty = 'Easy';

